window.VO = [{"id":"n01","text":"Sweden once made every driver on the road stop dead at ten to five one morning in 1967,","at":0.24,"t0":0.12,"t1":6.57},{"id":"n02","text":"because at five o'clock, the whole country would switch to driving on the right, like its neighbours.","at":13.58,"t0":6.79,"t1":11.93},{"id":"n03","text":"So when they all switched at once, did road deaths go up, or down?","at":24.76,"t0":12.38,"t1":15.79},{"id":"n04","text":"Ingrid had driven on the left her whole life, and one slip of habit would put her head-on into someone.","at":33.58,"t0":16.79,"t1":21.965},{"id":"n05","text":"Deaths went down, by almost half, because speed limits were cut that morning and everyone drove like a learner,","at":52.73,"t0":26.365,"t1":32.8},{"id":"n06","text":"and for two months, it looked as if the switch, Dagen_H, had made Sweden's roads safer overnight.","at":65.84,"t0":32.92,"t1":38.43},{"id":"n07","text":"But by November, the deaths were back where they'd been, because once the road felt normal, the care wore off.","at":77.96,"t0":38.98,"t1":44.615},{"id":"n08","text":"So the safest Ingrid ever drove was the morning she was sure she'd crash.","at":90.03,"t0":45.015,"t1":49.425}];
